export const LOCAL_CHECKS=[{id:'buyer',label:'Buyer and likely price checked'},{id:'inputs',label:'Seed, labour and equipment access checked'},{id:'calendar',label:'Sowing window and drainage discussed locally'}];
export function rotationCheckKey(sequence){return sequence.join('|')}
export function buildDecisionBrief({valid,rotation,financial,checks={}}){
 const remaining=LOCAL_CHECKS.filter(c=>!checks[c.id]);const result={remaining:remaining.map(c=>c.id),checked:LOCAL_CHECKS.length-remaining.length,total:LOCAL_CHECKS.length,selfReported:true,plantingApproval:false};
 if(!valid||!rotation)return {...result,state:'evidence',title:'Refresh the field evidence before comparing options',body:'The location or inputs no longer match the observations. Earlier numbers are paused.',action:'refresh',button:'Refresh observations'};
 if(rotation.id==='baseline')return {...result,state:'reference',title:'Your current practice stays on the table',body:'Use this as the reference. A change needs to justify its water, cost and management trade-offs.',action:'compare',button:'Compare an alternative'};
 if(rotation.deficit>0)return {...result,state:'water',title:'Resolve the remaining water gap first',body:`This option still lacks ${rotation.deficit.toLocaleString()} mm/year under your assumptions. Check the water source and seasonal timing before committing land.`,action:'water',button:'Review available irrigation'};
 if(financial?.status==='scenario'&&financial.firstYearNetChange<0)return {...result,state:'cost',title:'The switching costs need another look',body:'Your entered crop margins and switching costs leave a negative first-year balance. Confirm the buyer price or compare an option with lower transition costs.',action:'cost',button:'Review crop-margin assumptions'};
 if(financial?.status!=='scenario')return {...result,state:'cost-inputs',title:'Check whether the lower water demand pays for the switch',body:'Enter your own pumping cost, crop-margin change and switching cost. A lower annual water requirement alone does not establish a better financial outcome.',action:'cost',button:'Check the first-year costs'};
 if(remaining.length)return {...result,state:'local-checks',title:'Check what could rule out this rotation locally',body:'The annual water and entered cost screens pass, but buyer access, inputs and planting windows are still self-reported checks to complete.',action:'checks',button:'Review the remaining checks'};
 return {...result,state:'review',title:'A candidate for your local agronomist discussion',body:'Your entered screens and personal checks are recorded. Bring the option and its evidence to a local adviser; daily water adequacy, yields and suitability remain unvalidated.',action:'save',button:'Save the review brief'};
}
